```openscad
// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on z = 0, pockets open upward (+Z)

// ---------------- Parameters (mm) ----------------
block_x      = 86;     // block length along X
block_y      = 28;     // block width along Y
block_h      = 28;     // block height along Z

pocket_w     = 13.2;   // square pocket side (X and Y)
pocket_depth = 23;     // pocket depth from top face
pocket_n     = 4;      // number of pockets
pocket_pitch = 19.2;   // centre-to-centre spacing along X

floor_t      = block_h - pocket_depth; // floor under pockets (= 5 mm)
eps          = 0.5;    // overshoot so cuts pass cleanly through the top face

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : pocket_n - 1]) {
        x_c = (i - (pocket_n - 1)/2) * pocket_pitch;
        translate([x_c - pocket_w/2, -pocket_w/2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
