// Stand for 6 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward (+Z)

$fn = 64;               // curve resolution (no curved features, set per rules)

// ---- Block dimensions ----
block_x = 116;          // block length along X
block_y = 28;           // block width along Y
block_h = 32;           // block height along Z

// ---- Pocket dimensions ----
pocket_n     = 6;       // number of cuvette pockets
pocket_w     = 12.8;    // pocket square side (X and Y)
pocket_depth = 28;      // pocket depth from top face
pocket_pitch = 17.8;    // centre-to-centre spacing along X
floor_t      = block_h - pocket_depth; // floor thickness under pockets (4 mm)

// ---- Cutting overshoot ----
eps = 0.5;              // extension of cutters past the top face

// ---- Derived ----
row_start_x = -(pocket_n - 1) * pocket_pitch / 2; // first pocket centre X

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, opened from the top
    for (i = [0 : pocket_n - 1]) {
        translate([row_start_x + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
