```openscad
// Horizontal pipette rest
// Print orientation: base plate on bed (z = 0), uprights build upward (+Z)

$fn = 96;

// ---- Base plate ----
base_len    = 140;  // plate length along X (mm)
base_wid    = 35;   // plate width along Y (mm)
base_thk    = 4;    // plate thickness along Z (mm)

// ---- Uprights ----
up_thk      = 12;   // upright thickness along X (mm)
up_wid      = base_wid; // upright width along Y, same as plate (mm)
up_h        = 30;   // upright height from z = 0 (mm)

// ---- Cradle notch ----
notch_r     = 9;    // semicircular notch radius (mm), centred at y = 0, z = up_h
eps         = 0.5;  // overshoot for clean boolean cuts (mm)

// Upright positions: flush with each end of the plate
up_x = [-base_len/2, base_len/2 - up_thk];   // X start of each upright

module upright(x0) {
    difference() {
        translate([x0, -up_wid/2, 0])
            cube([up_thk, up_wid, up_h]);
        // Cradle: cylinder along X, centred on the top edge
        translate([x0 - eps, 0, up_h])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // Base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // Uprights at both ends
    for (x0 = up_x)
        upright(x0);
}
