// Horizontal pipette rest
// Units: mm. Print orientation: base plate on the bed (z = 0), building up +Z.

$fn = 96;

// ---- Base plate ----
base_len   = 180;   // plate length along X
base_wid   = 30;    // plate width along Y
base_thk   = 4;     // plate thickness along Z

// ---- Uprights ----
up_thk     = 10;    // upright thickness along X
up_wid     = base_wid; // upright width along Y (same as plate)
up_h       = 30;    // upright total height (z = 0 to 30)

// ---- Cradle notch ----
notch_r    = 10;    // semicircular notch radius
notch_y    = 0;     // notch centre Y
notch_z    = up_h;  // notch centre Z (on top edge)

eps        = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights, flush with each end of the plate
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - up_thk : -base_len/2, -up_wid/2, 0])
                cube([up_thk, up_wid, up_h]);
    }

    // Semicircular cradle notches cut through each upright along X
    for (sx = [-1, 1])
        translate([sx > 0 ? base_len/2 - up_thk - eps : -base_len/2 - eps, notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
}
