```openscad
// Horizontal pipette rest
// Print orientation: base plate on the bed (z = 0), uprights build in +Z

$fn = 96;

// ---- Base plate ----
plate_len   = 140;  // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 5;    // plate thickness along Z

// ---- Uprights ----
up_thk      = 10;   // upright thickness along X
up_height   = 35;   // upright top height (from z = 0)

// ---- Cradle notch ----
notch_r     = 9;    // semicircular notch radius
notch_z     = up_height; // notch centre height (on the top edge)
notch_y     = 0;    // notch centre Y position

eps         = 0.5;  // cutter overshoot past cut faces

module upright(x_center) {
    difference() {
        translate([x_center - up_thk/2, -plate_wid/2, 0])
            cube([up_thk, plate_wid, up_height]);
        // Cylindrical cradle running along X through the upright
        translate([x_center - up_thk/2 - eps, notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Uprights flush with each end of the plate
    for (s = [-1, 1])
        upright(s * (plate_len/2 - up_thk/2));
}
