// Horizontal pipette rest
// Units: mm. Print orientation: base plate flat on bed (z = 0), building +Z.

$fn = 96;                 // smoothness of curved surfaces

// ---------- Base plate ----------
base_len    = 180;        // plate length along X
base_wid    = 40;         // plate width along Y
base_thk    = 5;          // plate thickness (z = 0 to 5)

// ---------- Uprights ----------
upright_thk = 12;         // upright thickness along X
upright_wid = base_wid;   // upright width along Y (same as plate)
upright_h   = 40;         // upright height (z = 0 to 40)

// ---------- Cradle notch ----------
cradle_r    = 9;          // semicircular notch radius
cradle_y    = 0;          // notch centre Y
cradle_z    = upright_h;  // notch centre Z (on top edge)

// ---------- Cutting clearance ----------
eps         = 0.5;        // overshoot so cuts pass beyond faces

// Upright with cradle notch; x0 = X position of its low-X face
module upright(x0) {
    difference() {
        translate([x0, -upright_wid/2, 0])
            cube([upright_thk, upright_wid, upright_h]);
        // Cylinder along X, centred on top edge -> semicircular notch
        translate([x0 - eps, cradle_y, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_thk + 2*eps);
    }
}

union() {
    // Base plate, centred on origin in X and Y
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // Uprights flush with each end of the plate
    for (x0 = [-base_len/2, base_len/2 - upright_thk])
        upright(x0);
}
