```openscad
// Horizontal pipette rest
// Author: scocioba@gmail.com

$fn = 96;

// ---- Dimensions (mm) ----
base_len     = 180;   // base plate length (X)
base_w       = 30;    // base plate width (Y)
base_t       = 5;     // base plate thickness (Z)

upright_t    = 12;    // upright thickness along X
upright_h    = 40;    // upright total height from bed (Z)

cradle_r     = 7;     // cradle notch radius
cradle_z     = upright_h; // cradle centre height (on top edge)
cradle_y     = 0;     // cradle centre Y position

eps          = 0.5;   // cutter overshoot

// ---- Model ----
difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_w/2, 0])
            cube([base_len, base_w, base_t]);

        // Uprights, flush with each end
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - upright_t : -base_len/2, -base_w/2, 0])
                cube([upright_t, base_w, upright_h]);
    }

    // Semicircular cradle notches through each upright along X
    for (sx = [-1, 1])
        translate([sx * (base_len/2 - upright_t/2), cradle_y, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_t + 2*eps, center = true);
}
