```openscad
// Flat hex-cap wrench for reagent bottles
// Print orientation: plate lying flat on the bed, z = 0 to 6

// ---------------- Parameters ----------------
plate_t       = 6;     // plate thickness (Z)
head_d        = 40;    // round head diameter
handle_w      = 14;    // handle width (Y)
handle_x0     = 0;     // handle start (X)
handle_x1     = 120;   // handle end (X)
hex_af        = 26;    // hexagon size across flats
eps           = 0.5;   // cutter overshoot past faces

head_fn       = 128;   // facets for the round head

// Derived
hex_r = (hex_af / 2) / cos(30);   // hexagon circumradius (vertex distance)

// ---------------- Model ----------------
difference() {
    union() {
        // Round head centred on origin
        cylinder(d = head_d, h = plate_t, $fn = head_fn);

        // Straight handle, centred on y = 0
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal through-hole; $fn = 6 places vertices on the X axis,
    // so two flats are parallel to the X axis
    translate([0, 0, -eps])
        cylinder(r = hex_r, h = plate_t + 2 * eps, $fn = 6);
}
```

