// Hex key organiser block
// Prints standing on z = 0, pockets open at the top face.

// ---------------- Parameters ----------------
block_len    = 82;     // block length along X (mm)
block_wid    = 20;     // block width along Y (mm)
block_ht     = 25;     // block height along Z (mm)

pocket_depth = 12;     // depth of each hex pocket from the top face (mm)
pocket_pitch = 12;     // centre-to-centre spacing of pockets along X (mm)
pocket_af    = [1.9, 2.4, 2.9, 3.4, 4.4, 5.4]; // sizes across flats, -X to +X (mm)

overcut      = 0.5;    // extension of cutters past the top face (mm)

// Derived values
n_pockets    = len(pocket_af);
first_x      = -(n_pockets - 1) * pocket_pitch / 2;   // X of first pocket (centred row)

// Circumradius of a regular hexagon from its across-flats size
function hex_r(af) = af / sqrt(3);

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along the X axis (y = 0)
    // cylinder with $fn = 6 puts vertices on the X axis,
    // so two flats are parallel to the X axis.
    for (i = [0 : n_pockets - 1])
        translate([first_x + i * pocket_pitch, 0, block_ht - pocket_depth])
            cylinder(r = hex_r(pocket_af[i]),
                     h = pocket_depth + overcut,
                     $fn = 6);
}
