overlap      = 0.01;  // leg/plate fusion overlap

union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-win_x/2, -win_y/2, plate_bot_z - eps])
            cube([win_x, win_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with plate outer edges
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_w : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_d : -plate_y/2,
                   0])
            cube([leg_w, leg_d, leg_h + overlap]);
}
