// Wall mounting strip with two countersunk screw holes
// Print orientation: flat on the bed, countersinks facing up (+Z)

$fn = 96;

// ---------------- Bar dimensions ----------------
bar_length    = 50;    // X length of the bar (mm)
bar_width     = 24;    // Y width of the bar (mm)
bar_thickness = 6;     // Z thickness of the bar (mm)

// ---------------- Screw holes ----------------
hole_count    = 2;     // number of screw holes
hole_spacing  = 30;    // centre-to-centre distance along X (mm)
hole_d        = 4.5;   // through-hole diameter (mm)
csk_d         = 9;     // countersink diameter at the top surface (mm)
csk_angle     = 90;    // countersink included angle (degrees)

// ---------------- Derived values ----------------
eps       = 0.5;                                           // overshoot past cut faces (mm)
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2);     // depth of the cone (2.25 mm for 90 deg)
csk_top_d = csk_d + 2 * eps * tan(csk_angle / 2);          // cone diameter extended eps above the top face

// X positions of the holes, centred on the bar
function hole_x(i) = -hole_spacing * (hole_count - 1) / 2 + i * hole_spacing;

difference() {
    // Flat bar, centred in X and Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    for (i = [0 : hole_count - 1]) {
        translate([hole_x(i), 0, 0]) {
            // Through-hole, extended past bottom and top faces
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thickness + 2 * eps);

            // 90-degree countersink cone, from hole diameter up past the top face
            translate([0, 0, bar_thickness - csk_depth])
                cylinder(d1 = hole_d, d2 = csk_top_d, h = csk_depth + eps);
        }
    }
}
