notch_count   = 4;    // number of notches
notch_w       = 8;    // notch width (X)
notch_depth   = 12;   // notch depth into plate (along -Y)
notch_pitch   = 18;   // centre-to-centre spacing (X)

eps           = 0.5;  // overcut past faces

$fn = 64;

difference() {
    // Base plate, centred in X/Y, on bed
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Notches along +Y edge, centred along X
    for (i = [0 : notch_count - 1]) {
        x_c = (i - (notch_count - 1)/2) * notch_pitch;
        translate([x_c - notch_w/2,
                   plate_wid/2 - notch_depth,
                   -eps])
            cube([notch_w, notch_depth + eps, plate_thk + 2*eps]);
    }
}
